<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();
$role=(string)$_SESSION['role'];if(!in_array($role,['admin','director','sub_director','headteacher','bursar'],true)){http_response_code(403);exit('Your role cannot manage fee structures.');}$db=db();$uid=(int)$_SESSION['user_id'];$q=$db->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();$schoolIds=array_map('intval',array_column($schools,'id'));if(!$schoolIds){http_response_code(403);exit('No school is linked to your account.');}$school=(int)($_GET['school_id']??$schoolIds[0]);if(!in_array($school,$schoolIds,true)){http_response_code(403);exit('That school is outside your access.');}$schoolName='School';foreach($schools as $s)if((int)$s['id']===$school)$schoolName=$s['name'];$q=$db->prepare('SELECT id,name FROM school_classes WHERE school_id=? ORDER BY name');$q->execute([$school]);$classes=$q->fetchAll();$q=$db->prepare("SELECT f.*,c.name class_name,(SELECT COUNT(*) FROM fee_structure_items i WHERE i.structure_id=f.id) item_count,(SELECT COUNT(*) FROM fee_assessments a WHERE a.structure_id=f.id) assessment_count FROM fee_structures f JOIN school_classes c ON c.id=f.class_id AND c.school_id=f.school_id WHERE f.school_id=? ORDER BY f.academic_year DESC,f.term,c.name,f.created_at DESC");$q->execute([$school]);$structures=$q->fetchAll();$q=$db->prepare('SELECT * FROM fee_structure_items WHERE school_id=? ORDER BY structure_id,sequence_no');$q->execute([$school]);$itemsBy=[];foreach($q->fetchAll() as $i)$itemsBy[(int)$i['structure_id']][]=$i;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fee structures · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/api.js"></script><script defer src="assets/fee-structures.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> Fee structures</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e((string)($_SESSION['name']??'User'))?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">SCHOOL FINANCE</div><h1>Fee structures</h1><p class="muted"><?=e($schoolName)?> · Configure school-approved fees, then apply each published structure to active pupils once.</p></div><?php if(count($schools)>1):?><form method="get"><label for="fee-structure-school">School</label><select id="fee-structure-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$school?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></form><?php endif;?></section><div class="notice" role="note">Publishing locks the fee items. Applying creates auditable charge entries in the existing pupil ledgers. Reapplying will not duplicate assessments. Set your school’s amounts and term labels; no fee policy is prefilled.</div><section class="note-create"><div class="section-heading"><div><div class="eyebrow">NEW SCHEDULE</div><h2>Create fee structure draft</h2></div></div><form method="post" data-fee-structure-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="action" value="create"><div class="form-grid"><div><label for="fee-class">Class</label><select id="fee-class" name="class_id" required><option value="">Choose class</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label for="fee-year">Academic year</label><input id="fee-year" name="academic_year" type="number" min="2000" max="2100" value="<?=date('Y')?>" required></div><div><label for="fee-term">Term label</label><input id="fee-term" name="term" maxlength="40" placeholder="Use your school’s term label" required></div><div><label for="fee-title">Structure name</label><input id="fee-title" name="title" maxlength="180" placeholder="e.g. Term 1 fees" required></div></div><button class="button primary" type="submit">Create draft</button></form></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">SCHEDULES</div><h2>Fee structures</h2></div><span class="count-pill"><?=count($structures)?> structures</span></div><?php if($structures):?><?php foreach($structures as $f):$items=$itemsBy[(int)$f['id']]??[];$total=array_sum(array_map(fn($i)=>(float)$i['amount'],$items));?><article class="content-section"><div class="section-heading"><div><div class="eyebrow"><?=e($f['class_name'])?> · <?=e($f['academic_year'])?> · <?=e($f['term'])?></div><h3><?=e($f['title'])?></h3><p class="muted"><?=count($items)?> items · Total <?=number_format($total,2)?> · <?=number_format((int)$f['assessment_count'])?> pupil-item assessments created</p></div><span class="status-badge <?=e($f['status'])?>"><span></span><?=e(ucfirst($f['status']))?></span></div><?php if((int)$f['assessment_count']>0):?><p><a class="button" href="fee_invoices.php?school_id=<?=$school?>&amp;structure_id=<?=$f['id']?>">Invoice register</a></p><?php endif;?><?php if($items):?><div class="table-wrap"><table><thead><tr><th>Fee item</th><th>Amount</th><?php if($f['status']==='draft'):?><th>Action</th><?php endif;?></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['description'])?></td><td><?=number_format((float)$item['amount'],2)?></td><?php if($f['status']==='draft'):?><td><form method="post" data-fee-structure-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="action" value="delete_item"><input type="hidden" name="structure_id" value="<?=$f['id']?>"><input type="hidden" name="item_id" value="<?=$item['id']?>"><button class="button danger" type="submit">Remove</button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($f['status']==='draft'):?><form method="post" class="note-form" data-fee-structure-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="action" value="add_item"><input type="hidden" name="structure_id" value="<?=$f['id']?>"><div class="form-grid"><div><label>Description</label><input name="description" maxlength="180" required></div><div><label>Amount</label><input name="amount" type="number" min="0.01" max="100000000" step="0.01" required></div></div><button class="button" type="submit">Add fee item</button></form><?php if($items):?><form method="post" data-fee-structure-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="action" value="publish"><input type="hidden" name="structure_id" value="<?=$f['id']?>"><button class="button primary" type="submit">Publish structure</button></form><?php endif;?><form method="post" data-fee-structure-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="structure_id" value="<?=$f['id']?>"><button class="button" type="submit">Archive draft</button></form><?php elseif($f['status']==='published'):?><div class="ops-actions"><form method="post" data-fee-structure-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="action" value="apply"><input type="hidden" name="structure_id" value="<?=$f['id']?>"><button class="button primary" type="submit">Apply to active pupils</button></form><form method="post" data-fee-structure-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="structure_id" value="<?=$f['id']?>"><button class="button" type="submit">Archive</button></form></div><?php endif;?></article><?php endforeach;?><?php else:?><div class="empty-state"><h3>No fee structures yet</h3><p>Create one using the school’s approved amounts and term labels.</p></div><?php endif;?></section><footer class="page-footer">ShuleLite <span>·</span> School fee workflows</footer></div></main></div></body></html>
